sql.if:
and rule_config.system_id in (
    with recursive descendants(id) as (
        select id from telemetry_system_config
        where task_id = #{taskId} and device_satellite_id = #{deviceSatelliteId}
          and id = #{systemId} and is_deleted = 0
        union all
        select child.id from telemetry_system_config child
        inner join descendants parent on child.parent_id = parent.id
        where child.task_id = #{taskId}
          and child.device_satellite_id = #{deviceSatelliteId}
          and child.is_deleted = 0
    )
    select id from descendants
)

